import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (pos < buf.length && buf[pos] <= 32) pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > 32) pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= 32) pos++;
        boolean neg = buf[pos] == 45;
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > 32) r = r * 10 + (buf[pos++] - 48);
        return neg ? -r : r;
    }

    static int nextInt() { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        long n = nextLong(), m = nextLong(), k = nextLong();
        String s = next();
        long i = 0, run = 0, answer = 0;
        while (i < n) {
            run = s.charAt((int) i) == '0' ? run + 1 : 0;
            if (run == m) {
                answer++;
                i = Math.min(i, n - k) + k;
                run = 0;
            } else i++;
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	b := next()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	var r int64
	for _, c := range b {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	n, m, k := nextInt(), nextInt(), nextInt()
	s := next()
	var i, run, answer int64
	for i < n {
		if s[i] == '0' {
			run++
		} else {
			run = 0
		}
		if run == m {
			answer++
			i = min(i, n-k) + k
			run = 0
		} else {
			i++
		}
	}
	w.WriteString(strconv.FormatInt(answer, 10) + "\n")
}
